def parse_json(json_str):
    def parse_value(value_str):
        if value_str.startswith('"') and value_str.endswith('"'):
            return value_str[1:-1].replace('\\"', '"').replace("\\'", "'").replace("\\\\", "\\")
        if value_str == "true":
            return True
        if value_str == "false":
            return False
        if value_str == "null":
            return None
        try:
            return int(value_str)
        except ValueError:
            try:
                return float(value_str)
            except ValueError:
                return value_str

    def parse_array(array_str):
        array_str = array_str.strip()[1:-1].strip()
        if not array_str:
            return []
        elements = []
        while array_str:
            element, array_str = parse_value(array_str)
            elements.append(element)
            if array_str.startswith(","):
                array_str = array_str[1:].strip()
            else:
                break
        return elements

    def parse_object(object_str):
        object_str = object_str.strip()[1:-1].strip()
        if not object_str:
            return {}
        pairs = {}
        while object_str:
            key, object_str = parse_value(object_str)
            object_str = object_str.strip()[1:].strip()  # consume the ':'
            value, object_str = parse_value(object_str)
            pairs[key] = value
            if object_str.startswith(","):
                object_str = object_str[1:].strip()
            else:
                break
        return pairs

    def parse(json_str):
        json_str = json_str.strip()
        if json_str.startswith('['):
            return parse_array(json_str)
        elif json_str.startswith('{'):
            return parse_object(json_str)
        else:
            return parse_value(json_str)

    result = parse(json_str)
    if not result:
        raise ValueError("Invalid JSON string")
    return result

