            try:
                return float(value_str)
            except ValueError:
                return value_str

    def parse_array(array_str):
        array_str = array_str.strip('[]')
        elements = []
        level = 0
        current_value = ''
        for char in array_str:
            if char == ',' and level == 0:
                elements.append(parse_value(current_value))
                current_value = ''
            else:
                current_value += char
                if char == '[':
