def parse_json(json_str):
    def parse_value(value_str):
        if value_str == 'null':
            return None
        if value_str.startswith('"') and value_str.endswith('"'):
            return value_str[1:-1]
        if value_str.isdigit() or (value_str.startswith('-') and value_str[1:].isdigit()):
            return int(value_str)
        try:
            return float(value_str)
        except ValueError:
            pass
        if value_str.lower() in ['true', 'false']:
            return value_str.lower() == 'true'
        raise ValueError(f"Invalid value: {value_str}")

    def parse_list(lst_str):
        lst_str = lst_str.strip('[]')
        elements = lst_str.split(',')
        parsed_elements = []
        for element in elements:
            parsed_elements.append(parse_value(element.strip()))
        return parsed_elements

    def parse_dict(dct_str):
        dct_str = dct_str.strip('{}')
        key_value_pairs = dct_str.split(',')
        parsed_dict = {}
        for pair in key_value_pairs:
            key, value = pair.split(':')
            parsed_key = parse_value(key.strip())
            parsed_value = parse_value(value.strip())
            parsed_dict[parsed_key] = parsed_value
        return parsed_dict

    def parse_json_str(json_str):
        if json_str[0] == '{':
            return parse_dict(json_str)
        elif json_str[0] == '[':
            return parse_list(json_str)
        else:
            return parse_value(json_str)

