def parse_json(json_str):
    def parse_value(value_str):
        if value_str == 'null':
            return None
        if value_str.startswith('"') and value_str.endswith('"'):
            return value_str[1:-1]
        if value_str.startswith('"'):
            raise SyntaxError("Invalid string literal")
        try:
            return int(value_str)
        except ValueError:
            try:
                return float(value_str)
            except ValueError:
                if value_str.lower() == 'true':
                    return True
                if value_str.lower() == 'false':
                    return False
                raise ValueError("Invalid value")

    def parse_list(json_str):
        json_str = json_str[1:-1]  # Remove the brackets
        elements = []
        while json_str:
            json_str, element = parse_value(json_str)
            elements.append(element)
            if json_str.startswith(','):
                json_str = json_str[1:]
            else:
                break
        return json_str, elements

    def parse_dict(json_str):
        json_str = json_str[1:-1]  # Remove the brackets
        elements = {}
        while json_str:
            key, json_str = parse_value(json_str)
            if json_str.startswith(':'):
                json_str = json_str[1:]
                value, json_str = parse_value(json_str)
                elements[key] = value
            else:
                break
        return json_str, elements

    def parse_key_value_pair(json_str):
        key, json_str = parse_value(json_str)
        if json_str != ':':
            raise SyntaxError("Expected ':' after key")
        json_str = json_str[1:]  # Remove ':'
        value, json_str = parse_value(json_str)
        return json_str, key, value

    def parse(json_str):
        if not json_str:
            raise ValueError("Empty input")

        if json_str[0] == '[':
            return parse_list(json_str)
        elif json_str[0] == '{':
            return parse_dict(json_str)
        else:
            return parse_value(json_str)

    json_str = json_str.strip()
    if not json_str:
        raise ValueError("Empty input")

    json_str, result = parse(json_str)
    if json_str:
        raise SyntaxError("Unexpected trailing characters")

    return result

