def parse_json(json_str):
    def parse_value(value_str):
        if value_str.startswith('"') and value_str.endswith('"'):
            return value_str[1:-1].replace('\\"', '"').replace("\\'", "'")
        if value_str == "true":
            return True
        if value_str == "false":
            return False
        if value_str == "null":
            return None
        try:
            return int(value_str)
        except ValueError:
            try:
                return float(value_str)
            except ValueError:
                return value_str

    def parse_list(json_str):
        json_str = json_str[1:-1]  # Remove the brackets
        elements = []
        while json_str:
            json_str, element = parse_value(json_str)
            elements.append(element)
            if json_str.startswith(','):
                json_str = json_str[1:]
        return elements, json_str

    def parse_dict(json_str):
        json_str = json_str[1:-1]  # Remove the brackets
        elements = {}
        while json_str:
            key, json_str = parse_value(json_str)
            json_str = json_str[1:]  # Skip the colon
            value, json_str = parse_value(json_str)
            elements[key] = value
            if json_str.startswith(','):
                json_str = json_str[1:]
        return elements, json_str

    def parse(json_str):
        if json_str.startswith('['):
            return parse_list(json_str)
        elif json_str.startswith('{'):
            return parse_dict(json_str)
        else:
            return parse_value(json_str)

    stack = []
    result = None
    i = 0

    while i < len(json_str):
        if json_str[i] == '"':
            j = i + 1
            while j < len(json_str) and json_str[j] != '"':
                j += 1
            if j == len(json_str):
                raise SyntaxError("Unterminated string")
            result, json_str = parse_value(json_str[i:j + 1]), json_str[j + 1:]
            i = j
        elif json_str[i] in '[]{}':
            stack.append(json_str[i])
            i += 1
        elif json_str[i] in ',:':
            i += 1
        elif json_str[i].isspace():
            i += 1
        else:
            j = i
            while j < len(json_str) and json_str[j] not in ' ,[]{}':
                j += 1
            value = json_str[i:j]
            if value.isdigit() or (value.startswith('-') and value[1:].isdigit()):
                result = int(value)
            elif value.replace('.', '', 1).isdigit() or (value.startswith('-') and value[1:].replace('.', '', 1).isdigit()):
                result = float(value)
            elif value.lower() == 'true':
                result = True
            elif value.lower() == 'false':
                result = False
            elif value.lower() == 'null':
                result = None
            else:
                result = value
            i = j

    if len(stack) != 0:
        raise SyntaxError("Unmatched brackets or braces")

    if result is None:
        raise SyntaxError("Empty JSON string")

